def auto_compact({{messages}}, {{tokenizer}}, {{budget}}, {{summarise_fn}}):
    total = sum(len({{tokenizer}}.encode(m["content"])) for m in {{messages}})
    if total <= {{budget}}: return {{messages}}
    head, tail = {{messages}}[:-6], {{messages}}[-6:]
    digest = {{summarise_fn}}("\n".join(m["content"] for m in head))
    return [{"role": "system", "content": f"Earlier: {digest}"}] + tail
